#!/usr/bin/env bash
# html-report :: new-report.sh — scaffold a new report directory
#
# Usage:
#   new-report.sh <name> <output-base-dir>
#
# Creates <output-base-dir>/<name>/ with:
#   <name>.html        (scaffold with <!-- Generated by Trae Work --> comment)
#   assets/            (for generated/downloaded images)
#   _shared/js/        (for JS libraries copied on demand)
#   _shared/fonts/     (empty, model copies needed fonts here)

set -euo pipefail

NAME="${1:-}"
BASE_DIR="${2:-}"

if [[ -z "$NAME" || -z "$BASE_DIR" ]]; then
  echo "usage: new-report.sh <name> <output-base-dir>" >&2
  echo "" >&2
  echo "  <name>            Report directory name (also used as HTML filename)" >&2
  echo "  <output-base-dir> Directory where <name>/ will be created (your work dir)" >&2
  exit 1
fi

HERE="$(cd "$(dirname "$0")/.." && pwd)"

# Resolve base dir
if [[ "$BASE_DIR" != /* ]]; then
  BASE_DIR="$PWD/$BASE_DIR"
fi

OUT_DIR="$BASE_DIR/$NAME"
if [[ -e "$OUT_DIR" ]]; then
  echo "error: $OUT_DIR already exists" >&2
  exit 1
fi

# --- Create directory structure ---
mkdir -p "$OUT_DIR/assets" "$OUT_DIR/_shared/js" "$OUT_DIR/_shared/fonts"

# --- Generate scaffold HTML ---
cat > "$OUT_DIR/$NAME.html" << 'HTML'
<!-- Generated by Trae Work -->
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Report</title>

  <style>
    /* === Font faces — filled by agent per chosen theme === */
    /*
    @font-face {
      font-family: 'SansName';
      src: url('./_shared/fonts/SansName-Regular.ttf') format('truetype');
      font-weight: 400;
    }
    @font-face {
      font-family: 'SansName';
      src: url('./_shared/fonts/SansName-Bold.ttf') format('truetype');
      font-weight: 700;
    }
    @font-face {
      font-family: 'MonoName';
      src: url('./_shared/fonts/MonoName-Regular.ttf') format('truetype');
      font-weight: 400;
    }
    */
  </style>

  <style>
    /* Replace the top-level marker below once with the selected complete
       :root color block from references/color-system.md. */
    /* ACTIVE_PALETTE_TOKENS */

    /* === Structural variables === */
    :root {
      --space-1: 4px;
      --space-2: 8px;
      --space-3: 12px;
      --space-4: 16px;
      --space-5: 24px;
      --space-6: 32px;
      --space-7: 48px;
      --space-8: 64px;
      --radius-sm: 4px;
      --radius-md: 8px;
      --radius-lg: 12px;
      --radius-pill: 999px;
      --font-sans: 'SansName', 'PingFang SC', 'Microsoft YaHei', 'Noto Sans CJK SC', sans-serif;
      --font-serif: Georgia, 'Times New Roman', serif;
      --font-mono: 'MonoName', 'SFMono-Regular', Consolas, monospace;
      --font-metric: var(--font-sans);
      --max: 960px;
    }

    /* === Base styles === */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { font-size: 16px; scroll-behavior: smooth; }
    body {
      font-family: var(--font-sans);
      color: var(--ink);
      background: var(--bg);
      line-height: 1.7;
      padding: 2rem 0;
    }
    article.page {
      width: 100%;
    }
    .page__content,
    .report-intro__surface {
      width: calc(100% - 2rem);
      max-width: var(--max);
      margin: 0 auto;
    }
    .table-wrap { width: 100%; overflow: visible; }
    table { width: 100%; border-collapse: collapse; table-layout: auto; }
    th, td {
      padding: var(--space-2) var(--space-3);
      border-bottom: 1px solid var(--rule);
      text-align: left;
      vertical-align: top;
      overflow-wrap: anywhere;
    }
    img, svg, canvas { max-width: 100%; height: auto; }
    /* Full-width mode shell; no layout modifier keeps the contained surface. */
    .report-intro {
      margin-bottom: var(--space-7);
    }
    .report-intro__surface {
      position: relative;
      isolation: isolate;
      overflow: hidden;
      color: var(--page-brand-text, var(--ink));
      background: var(--page-brand-soft, var(--page-surface-muted, var(--bg2)));
      border-radius: var(--radius-lg);
      padding: var(--space-7);
    }
    .report-intro__content {
      position: relative;
      z-index: 1;
      max-width: 760px;
    }
    .report-intro:not(.report-intro--integrated):not(.report-intro--stage):not(.report-intro--with-media):not(.report-intro--plain) .report-intro__surface::before,
    .report-intro:not(.report-intro--integrated):not(.report-intro--stage):not(.report-intro--with-media):not(.report-intro--plain) .report-intro__surface::after {
      content: "";
      position: absolute;
      z-index: 0;
      pointer-events: none;
    }
    .report-intro:not(.report-intro--integrated):not(.report-intro--stage):not(.report-intro--with-media):not(.report-intro--plain) .report-intro__surface::before {
      width: 180px;
      height: 180px;
      top: -72px;
      right: -48px;
      border-radius: 50%;
      background: var(--page-brand-soft-strong, var(--page-surface-muted, var(--bg2)));
      opacity: 0.72;
    }
    .report-intro:not(.report-intro--integrated):not(.report-intro--stage):not(.report-intro--with-media):not(.report-intro--plain) .report-intro__surface::after {
      width: 136px;
      height: 96px;
      right: 96px;
      bottom: -36px;
      border-radius: var(--radius-lg);
      background: var(--page-surface, var(--bg));
      opacity: 0.58;
      transform: rotate(-8deg);
    }
    .report-intro h1 {
      line-height: 1.2;
      overflow-wrap: anywhere;
    }
    .report-intro__summary {
      max-width: 70ch;
      margin-top: var(--space-3);
      color: var(--page-text-secondary, var(--text-secondary, var(--muted)));
    }
    @media (max-width: 768px) {
      body { padding: 1rem 0; }
      .report-intro__surface { padding: var(--space-5); }
      .report-intro:not(.report-intro--integrated):not(.report-intro--stage):not(.report-intro--with-media):not(.report-intro--plain) .report-intro__surface::before {
        width: 124px;
        height: 124px;
        top: -44px;
        right: -52px;
        opacity: 0.38;
      }
      .report-intro:not(.report-intro--integrated):not(.report-intro--stage):not(.report-intro--with-media):not(.report-intro--plain) .report-intro__surface::after {
        display: none;
      }
    }
    @media print, (forced-colors: active) {
      .report-intro__surface::before,
      .report-intro__surface::after { display: none; }
    }
  </style>
</head>
<body>
  <article class="page">
    <header class="report-intro">
      <div class="report-intro__surface">
        <div class="report-intro__content">
          <h1>Report Title</h1>
          <p class="report-intro__summary">Summarize the report's main conclusion in one or two sentences.</p>
        </div>
      </div>
    </header>
    <div class="page__content">
      <main>
        <section>
          <h2>Section 1</h2>
          <p>Content goes here.</p>
        </section>
      </main>
      <footer>
        <div class="sources">
          <h2>Sources</h2>
          <ol></ol>
        </div>
      </footer>
    </div>
  </article>

  <!-- Shared JS — uncomment what you need -->
  <!-- <script src="./_shared/js/echarts.min.js"></script> -->
  <!-- <script src="./_shared/js/mermaid.min.js"></script> -->
  <!-- <script src="./assets/charts.js"></script> -->
</body>
</html>
HTML

echo "✔ Created: $OUT_DIR/$NAME.html"
echo "✔ Created: $OUT_DIR/assets/"
echo "✔ Created: $OUT_DIR/_shared/js/ (copy needed JS here from $HERE/assets/js/)"
echo "✔ Created: $OUT_DIR/_shared/fonts/ (copy needed fonts here from $HERE/canvas-fonts/)"
